1	/**
2	 * Claude executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, materializes the
5	 * implementation repo, spawns `claude -p`, and writes ExecutorResult
6	 * to result.json at RESULT_PATH.
7	 *
8	 * Formal ABI env vars (from ExecutorInput):
9	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID
10	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_REPO_PATH
11	 *   BRIEFING_PATH, RESULT_PATH
12	 *   BUDGET_TOKENS (optional)
13	 *   SSH_KEY_PATH, GITHUB_TOKEN
14	 *
15	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
16	 *   WORKSPACE_ROOT     — management repo root for task YAML reading
17	 *   TASK_BRANCH        — management repo feature branch for git commits
18	 *   GIT_AUTHOR_EMAIL   — for commit identity
19	 *   GIT_AUTHOR_NAME    — for commit identity
20	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
21	 *   MAX_TURNS          — max claude CLI turns (default: 200)
22	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
23	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
24	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
25	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
26	 */
27	
28	import { spawn, execSync } from "node:child_process";
29	import {
30	  mkdirSync,
31	  appendFileSync,
32	  readFileSync,
33	  writeFileSync,
34	  existsSync,
35	  readdirSync,
36	  rmSync,
37	  copyFileSync,
38	  lstatSync,
39	} from "node:fs";
40	import { join, dirname } from "node:path";
41	import { homedir } from "node:os";
42	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
43	import type { ExecutorResult } from "@workflow/runtime-abi";
44	import { isValidResult } from "@workflow/runtime-abi";
45	import { extractTokenUsage } from "./token-usage.js";
46	
47	// ── Helpers ───────────────────────────────────────────────────────────────────
48	
49	function requireEnv(name: string): string {
50	  const val = process.env[name];
51	  if (!val) throw new Error(`Required env var ${name} is not set`);
52	  return val;
53	}
54	
55	function emit(event: Record<string, unknown>): void {
56	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
57	}
58	
59	function buildGitEnv(sshKeyPath: string | undefined): NodeJS.ProcessEnv {
60	  if (!sshKeyPath) return process.env;
61	  return {
62	    ...process.env,
63	    GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new`,
64	  };
65	}
66	
67	/**
68	 * Materialize the implementation repo at taskRepoPath:
69	 *   - If path exists and origin matches URL: fetch + checkout + pull
70	 *   - Otherwise: clone fresh
71	 */
72	function materializeRepo(
73	  taskRepoUrl: string,
74	  taskRepoBranch: string,
75	  taskRepoPath: string,
76	  sshKeyPath: string | undefined,
77	): void {
78	  const env = buildGitEnv(sshKeyPath);
79	  const opts = { env, stdio: "pipe" as const };
80	
81	  if (existsSync(join(taskRepoPath, ".git"))) {
82	    let originUrl = "";
83	    try {
84	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
85	        ...opts, encoding: "utf-8",
86	      }).trim();
87	    } catch { /* no remote — fall through to clone */ }
88	
89	    if (originUrl === taskRepoUrl) {
90	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
91	      execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
92	      try {
93	        execSync(
94	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
95	          opts,
96	        );
97	      } catch { /* ff-only may fail on diverged — ok, we just checked out */ }
98	      return;
99	    }
100	  }
101	
102	  // Clone fresh.
103	  mkdirSync(dirname(taskRepoPath), { recursive: true });
104	  if (existsSync(taskRepoPath)) {
105	    rmSync(taskRepoPath, { recursive: true, force: true });
106	  }
107	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
108	  execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
109	}
110	
111	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
112	  { file: "yarn.lock",        tool: "yarn"    },
113	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
114	  { file: "go.mod",           tool: "go"      },
115	  { file: "requirements.txt", tool: "python3" },
116	  { file: "pyproject.toml",   tool: "python3" },
117	  { file: "Cargo.toml",       tool: "cargo"   },
118	];
119	
120	function checkRequiredTools(taskRepoPath: string): string[] {
121	  const missing: string[] = [];
122	  const checked = new Set<string>();
123	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
124	    if (checked.has(tool)) continue;
125	    if (!existsSync(join(taskRepoPath, file))) continue;
126	    checked.add(tool);
127	    try {
128	      execSync(`which ${tool}`, { stdio: "pipe" });
129	    } catch {
130	      missing.push(tool);
131	    }
132	  }
133	  return missing;
134	}
135	
136	function copyWorkspaceClaude(workspaceRoot: string): void {
137	  const src = join(workspaceRoot, "CLAUDE.md");
138	  if (!existsSync(src)) return;
139	  const destDir = join(homedir(), ".claude");
140	  mkdirSync(destDir, { recursive: true });
141	  copyFileSync(src, join(destDir, "CLAUDE.md"));
142	}
143	
144	function copyDirRecursive(src: string, dest: string): void {
145	  mkdirSync(dest, { recursive: true });
146	  for (const entry of readdirSync(src)) {
147	    const srcPath = join(src, entry);
148	    const destPath = join(dest, entry);
149	    const stat = lstatSync(srcPath);
150	    if (stat.isDirectory()) {
151	      copyDirRecursive(srcPath, destPath);
152	    } else if (stat.isFile()) {
153	      copyFileSync(srcPath, destPath);
154	    }
155	  }
156	}
157	
158	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
159	  const globalSkillsDir = join(homedir(), ".claude", "skills");
160	  if (existsSync(globalSkillsDir)) {
161	    rmSync(globalSkillsDir, { recursive: true, force: true });
162	  }
163	  mkdirSync(globalSkillsDir, { recursive: true });
164	
165	  const copySkillsFrom = (sourceDir: string): void => {
166	    if (!existsSync(sourceDir)) return;
167	    let entries: string[];
168	    try { entries = readdirSync(sourceDir); } catch { return; }
169	    for (const entry of entries) {
170	      const srcPath = join(sourceDir, entry);
171	      try {
172	        const stat = lstatSync(srcPath);
173	        if (!stat.isDirectory()) continue;
174	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
175	      } catch (e) {
176	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
177	      }
178	    }
179	  };
180	
181	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
182	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
183	
184	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
185	  if (existsSync(wsSkillsDir)) {
186	    let entries: string[];
187	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
188	    for (const entry of entries) {
189	      if (entry === ".gitignore") continue;
190	      const srcPath = join(wsSkillsDir, entry);
191	      try {
192	        const stat = lstatSync(srcPath);
193	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
194	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
195	      } catch (e) {
196	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
197	      }
198	    }
199	  }
200	}
201	
202	function writeResult(resultPath: string, result: ExecutorResult): void {
203	  mkdirSync(dirname(resultPath), { recursive: true });
204	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
205	}
206	
207	// ── Main ──────────────────────────────────────────────────────────────────────
208	
209	async function main(): Promise<void> {
210	  // ── Read formal ABI env vars ────────────────────────────────────────────────
211	  let taskId: string;
212	  let featureId: string;
213	  let taskRepoUrl: string;
214	  let taskRepoBranch: string;
215	  let taskRepoPath: string;
216	  let briefingPath: string;
217	  let resultPath: string;
218	  let sshKeyPath: string | undefined;
219	  let githubToken: string;
220	
221	  try {
222	    taskId = requireEnv("TASK_ID");
223	    featureId = requireEnv("FEATURE_ID");
224	    taskRepoUrl = requireEnv("TASK_REPO_URL");
225	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
226	    taskRepoPath = requireEnv("TASK_REPO_PATH");
227	    briefingPath = requireEnv("BRIEFING_PATH");
228	    resultPath = requireEnv("RESULT_PATH");
229	    githubToken = process.env.GITHUB_TOKEN ?? "";
230	    sshKeyPath = process.env.SSH_KEY_PATH || undefined;
231	  } catch (e) {
232	    emit({ type: "executor_fatal", details: (e as Error).message });
233	    process.exit(1);
234	  }
235	
236	  const budgetTokensStr = process.env.BUDGET_TOKENS;
237	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
238	
239	  // Day-1 single-container extras.
240	  const workspaceRoot = process.env.WORKSPACE_ROOT ?? "";
241	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
242	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
243	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
244	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
245	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
246	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
247	  const mcpRagUrl = process.env.MCP_RAG_URL;
248	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
249	
250	  const runStartIso = new Date().toISOString();
251	
252	  // ── 1. Materialize implementation repo ─────────────────────────────────────
253	  try {
254	    materializeRepo(taskRepoUrl, taskRepoBranch, taskRepoPath, sshKeyPath);
255	  } catch (e) {
256	    const details = `repo materialization failed: ${String(e)}`;
257	    emit({ type: "executor_fatal", task_id: taskId, details });
258	    writeResult(resultPath, {
259	      terminal_status: "failed",
260	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
261	    });
262	    process.exit(0);
263	  }
264	
265	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
266	  const missingTools = checkRequiredTools(taskRepoPath);
267	  if (missingTools.length > 0) {
268	    const details = `missing tools: ${missingTools.join(", ")}`;
269	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
270	    writeResult(resultPath, {
271	      terminal_status: "blocked",
272	      blocked_reason: "missing_tool",
273	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
274	    });
275	    process.exit(0);
276	  }
277	
278	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
279	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
280	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
281	
282	  // ── 4. Read briefing ────────────────────────────────────────────────────────
283	  let briefingContent: string;
284	  try {
285	    briefingContent = readFileSync(briefingPath, "utf-8");
286	  } catch (e) {
287	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
288	    writeResult(resultPath, {
289	      terminal_status: "failed",
290	      blocked_reason: `briefing_read_failed: ${String(e)}`,
291	    });
292	    process.exit(0);
293	  }
294	
295	  // Append hard-stop rule for missing tools.
296	  const effectiveBriefing =
297	    briefingContent +
298	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
299	
300	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
301	  const mcpArgs: string[] = [];
302	  if (mcpRagUrl || figmaToken) {
303	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
304	    if (mcpRagUrl) {
305	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
306	    }
307	    if (figmaToken) {
308	      mcpConfig.mcpServers["figma"] = {
309	        type: "stdio",
310	        command: "npx",
311	        args: ["-y", "@figma/mcp-server"],
312	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
313	      };
314	    }
315	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
316	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
317	    mcpArgs.push("--mcp-config", mcpConfigPath);
318	  }
319	
320	  // ── 6. Spawn claude ─────────────────────────────────────────────────────────
321	  const claudeEnv = {
322	    ...buildGitEnv(sshKeyPath),
323	    CLAUDE_AGENT_RUNTIME: "1",
324	    RESULT_PATH: resultPath,
325	    GITHUB_TOKEN: githubToken,
326	    ...(sshKeyPath ? { SSH_KEY_PATH: sshKeyPath } : {}),
327	  };
328	
329	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
330	
331	  const spawnResult = await new Promise<{
332	    stdout: string;
333	    status: number | null;
334	    signal: string | null;
335	    error?: Error;
336	  }>((resolve) => {
337	    const stdoutChunks: string[] = [];
338	
339	    const child = spawn(
340	      "claude",
341	      [
342	        "-p", effectiveBriefing,
343	        "--max-turns", String(maxTurns),
344	        "--output-format", "stream-json",
345	        "--verbose",
346	        "--dangerously-skip-permissions",
347	        ...mcpArgs,
348	      ],
349	      { cwd: taskRepoPath, env: claudeEnv },
350	    );
351	
352	    child.stdout.setEncoding("utf-8");
353	    child.stderr.setEncoding("utf-8");
354	
355	    let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
356	    child.stdout.on("data", (chunk: string) => {
357	      stdoutChunks.push(chunk);
358	      process.stdout.write(chunk);
359	      if (resultWatchdog === null && chunk.includes('"type":"result"')) {
360	        resultWatchdog = setTimeout(() => {
361	          if (!child.killed) child.kill("SIGTERM");
362	        }, 30_000);
363	      }
364	    });
365	
366	    child.stderr.on("data", (chunk: string) => {
367	      process.stderr.write(chunk);
368	    });
369	
370	    child.on("error", (err: Error) => {
371	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
372	      resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
373	    });
374	
375	    child.on("exit", () => {
376	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
377	      setTimeout(() => {
378	        if (!child.stdout.destroyed) child.stdout.destroy();
379	        if (!child.stderr.destroyed) child.stderr.destroy();
380	      }, 0);
381	    });
382	
383	    child.on("close", (code: number | null, signal: string | null) => {
384	      resolve({ stdout: stdoutChunks.join(""), status: code, signal });
385	    });
386	  });
387	
388	  emit({
389	    type: "claude_exit",
390	    task_id: taskId,
391	    feature_id: featureId,
392	    exit_code: spawnResult.status,
393	    signal: spawnResult.signal ?? null,
394	  });
395	
396	  // ── 7. Token audit ──────────────────────────────────────────────────────────
397	  const tokenUsage = spawnResult.stdout
398	    ? extractTokenUsage(spawnResult.stdout)
399	    : undefined;
400	
401	  if (tokenUsage === undefined) {
402	    emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
403	  } else {
404	    emit({
405	      type: "budget_audit",
406	      task_id: taskId,
407	      feature_id: featureId,
408	      total_tokens: tokenUsage.input + tokenUsage.output,
409	      max_tokens: budgetTokens,
410	    });
411	  }
412	
413	  // ── 8. Check for result.json written by Claude ──────────────────────────────
414	  if (existsSync(resultPath)) {
415	    let raw: unknown;
416	    try {
417	      raw = JSON.parse(readFileSync(resultPath, "utf-8"));
418	    } catch {
419	      raw = null;
420	    }
421	    if (isValidResult(raw)) {
422	      // Claude wrote a valid result — augment with token_usage if available.
423	      const claudeResult = raw as ExecutorResult;
424	      if (tokenUsage !== undefined && !claudeResult.token_usage) {
425	        claudeResult.token_usage = tokenUsage;
426	      }
427	
428	      // Budget exceeded check.
429	      if (
430	        budgetTokens !== undefined &&
431	        tokenUsage !== undefined &&
432	        tokenUsage.input + tokenUsage.output > budgetTokens
433	      ) {
434	        writeResult(resultPath, {
435	          terminal_status: "blocked",
436	          blocked_reason: "budget_exceeded",
437	          token_usage: tokenUsage,
438	        });
439	      } else {
440	        writeResult(resultPath, claudeResult);
441	      }
442	
443	      // Flush log (best-effort).
444	      if (logSinkEnabled && workspaceRoot && taskBranch) {
445	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath);
446	      }
447	      process.exit(0);
448	    }
449	  }
450	
451	  // ── 9. Claude did not write result.json — determine from task YAML ──────────
452	  // Day-1 fallback: if Claude didn't write result.json, read the task YAML.
453	  if (workspaceRoot) {
454	    let taskStatus = "in_progress";
455	    let blockedReason: string | undefined;
456	    let blockedSuggestion: string | undefined;
457	
458	    try {
459	      const yamlPath = join(workspaceRoot, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
460	      const taskData = parseYaml(readFileSync(yamlPath, "utf-8")) as {
461	        status: string;
462	        blocked_reason?: string;
463	        blocked_suggestion?: string;
464	      };
465	      taskStatus = taskData.status;
466	      blockedReason = taskData.blocked_reason;
467	      blockedSuggestion = taskData.blocked_suggestion;
468	    } catch { /* use in_progress */ }
469	
470	    let result: ExecutorResult;
471	    if (taskStatus === "in_review") {
472	      result = { terminal_status: "in_review", ...(tokenUsage ? { token_usage: tokenUsage } : {}) };
473	    } else if (taskStatus === "blocked") {
474	      result = {
475	        terminal_status: "blocked",
476	        blocked_reason: blockedReason ?? "unknown",
477	        ...(blockedSuggestion ? { blocked_suggestion: blockedSuggestion } : {}),
478	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
479	      };
480	    } else {
481	      // task still in_progress — claude exited without completing
482	      const note = spawnResult.error
483	        ? `process error: ${spawnResult.error.message}`
484	        : `task still in_progress after claude exit (code ${spawnResult.status ?? "null"})`;
485	      result = {
486	        terminal_status: "failed",
487	        blocked_reason: `runtime_error: ${note}`,
488	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
489	      };
490	    }
491	
492	    if (
493	      budgetTokens !== undefined &&
494	      tokenUsage !== undefined &&
495	      tokenUsage.input + tokenUsage.output > budgetTokens &&
496	      result.terminal_status !== "failed"
497	    ) {
498	      result = {
499	        terminal_status: "blocked",
500	        blocked_reason: "budget_exceeded",
501	        token_usage: tokenUsage,
502	      };
503	    }
504	
505	    writeResult(resultPath, result);
506	
507	    if (logSinkEnabled && taskBranch) {
508	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, result.terminal_status, sshKeyPath);
509	    }
510	    process.exit(0);
511	  }
512	
513	  // No workspaceRoot and no result.json — treat as failure.
514	  writeResult(resultPath, {
515	    terminal_status: "failed",
516	    blocked_reason: "no_result_and_no_workspace_root",
517	    ...(tokenUsage ? { token_usage: tokenUsage } : {}),
518	  });
519	  process.exit(0);
520	}
521	
522	// ── Log flush (best-effort) ───────────────────────────────────────────────────
523	
524	function flushLog(
525	  workspaceRoot: string,
526	  featureId: string,
527	  taskId: string,
528	  taskBranch: string,
529	  runStartIso: string,
530	  gitAuthorEmail: string,
531	  gitAuthorName: string,
532	  stdout: string,
533	  outcome: string,
534	  sshKeyPath: string | undefined,
535	): void {
536	  try {
537	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
538	    mkdirSync(logsDir, { recursive: true });
539	
540	    const safeIso = runStartIso.replace(/[:.]/g, "-");
541	    const logFilename = `${safeIso}.jsonl`;
542	    const logPath = join(logsDir, logFilename);
543	
544	    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
545	    if (stdout) {
546	      appendFileSync(logPath, stdout.endsWith("\n") ? stdout : stdout + "\n");
547	    }
548	    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");
549	
550	    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
551	    const env = {
552	      ...process.env,
553	      GIT_AUTHOR_NAME: gitAuthorName,
554	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
555	      GIT_COMMITTER_NAME: gitAuthorName,
556	      GIT_COMMITTER_EMAIL: gitAuthorEmail,
557	      ...(sshKeyPath ? { GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` } : {}),
558	    };
559	    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };
560	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
561	    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
562	    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
563	    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
564	  } catch { /* best-effort */ }
565	}
566	
567	main().catch((e) => {
568	  try {
569	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
570	  } catch { /* last resort */ }
571	  process.exit(1);
572	});
