import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import Ajv, { type ValidateFunction, type ErrorObject } from "ajv";
import { parse as parseYaml } from "yaml";

/** Validated agent configuration. */
export interface AgentConfig {
  /** SSH URLs of workspace repositories this agent watches. */
  watches: string[];
  /** Kill switch — false means exit immediately. */
  enabled: boolean;
  /** Maximum random jitter (seconds) before a claim commit. */
  jitter_max_seconds: number;
  /** Hard budget limits per task activation. */
  budget: {
    /** Max tokens (input + output) per task. */
    max_tokens_per_task: number;
    /** Max tool-use loop iterations per task. */
    max_iterations: number;
  };
  /** Per-run JSONL event log configuration. */
  log_sink: {
    /** Whether to write event logs. */
    enabled: boolean;
  };
  /**
   * Seconds to sleep between poll cycles when no eligible task is found,
   * and after a successful task run.
   * Set to 0 for single-shot mode (process exits after one cycle).
   * Defaults to 60 when omitted.
   */
  idle_sleep_seconds?: number;
  /**
   * How often (in seconds) the agent checks in_review PR mergeability.
   * The in_review pass is skipped if it ran within this window.
   * Defaults to idle_sleep_seconds when omitted.
   * Raise to 300 in production to reduce GitHub API call frequency.
   */
  pr_poll_interval_seconds?: number;
}

export interface ValidationError {
  /** JSON pointer to the offending field (e.g. "/budget/max_tokens_per_task"). */
  path: string;
  /** Human-readable description of what went wrong. */
  message: string;
}

export type ValidationResult =
  | { valid: true; config: AgentConfig }
  | { valid: false; errors: ValidationError[] };

const __dirname = dirname(fileURLToPath(import.meta.url));
const SCHEMA_PATH = resolve(__dirname, "../../../schemas/agent.schema.json");

let _ajvValidate: ValidateFunction | null = null;

function getValidator(schemaOverride?: object): ValidateFunction {
  if (schemaOverride) {
    const ajv = new Ajv.default({ allErrors: true });
    return ajv.compile(schemaOverride);
  }
  if (!_ajvValidate) {
    const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf-8"));
    const ajv = new Ajv.default({ allErrors: true });
    _ajvValidate = ajv.compile(schema);
  }
  return _ajvValidate;
}

function formatAjvErrors(errors: ErrorObject[]): ValidationError[] {
  return errors.map((err: ErrorObject) => {
    const path = err.instancePath || "/";
    let message: string;

    switch (err.keyword) {
      case "required":
        message = `Missing required field: ${err.params.missingProperty}`;
        break;
      case "additionalProperties":
        message = `Unknown field: ${err.params.additionalProperty}`;
        break;
      case "type":
        message = `Expected type "${err.params.type}", got ${typeof err.data}`;
        break;
      case "minimum":
        message = `Value must be >= ${err.params.limit}`;
        break;
      case "minItems":
        message = `Array must have at least ${err.params.limit} item(s)`;
        break;
      case "minLength":
        message = `String must not be empty`;
        break;
      default:
        message = err.message ?? "Validation failed";
    }

    return { path, message };
  });
}

/**
 * Parse a YAML string and validate it against the agent.yaml schema.
 * Returns the validated AgentConfig on success, or structured errors on failure.
 */
export function validateAgentYaml(
  yamlContent: string,
  options?: { schema?: object },
): ValidationResult {
  let data: unknown;
  try {
    data = parseYaml(yamlContent);
  } catch (e) {
    return {
      valid: false,
      errors: [{ path: "/", message: `YAML parse error: ${(e as Error).message}` }],
    };
  }

  if (data === null || data === undefined || typeof data !== "object") {
    return {
      valid: false,
      errors: [{ path: "/", message: "Document must be a YAML mapping (object)" }],
    };
  }

  const validate = getValidator(options?.schema);
  const isValid = validate(data);

  if (!isValid) {
    return {
      valid: false,
      errors: formatAjvErrors(validate.errors ?? []),
    };
  }

  return { valid: true, config: data as AgentConfig };
}

/**
 * Load and validate an agent.yaml file from disk.
 * Throws if the file cannot be read. Returns a ValidationResult.
 */
export function loadAgentYaml(
  filePath: string,
  options?: { schema?: object },
): ValidationResult {
  const content = readFileSync(filePath, "utf-8");
  return validateAgentYaml(content, options);
}

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { validateAgentYaml, type AgentConfig } from "../src/config/validate-agent-yaml.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const fixture = (name: string) =>
  readFileSync(resolve(__dirname, "fixtures", name), "utf-8");

const schema = JSON.parse(
  readFileSync(resolve(__dirname, "../../schemas/agent.schema.json"), "utf-8"),
);

describe("validateAgentYaml", () => {
  describe("valid configs", () => {
    it("accepts the full example file", () => {
      const result = validateAgentYaml(fixture("valid-agent.yaml"), { schema });
      expect(result.valid).toBe(true);
      if (!result.valid) return;
      expect(result.config.watches).toEqual([
        "git@github.com:mycompany/workspace.git",
      ]);
      expect(result.config.enabled).toBe(true);
      expect(result.config.jitter_max_seconds).toBe(15);
      expect(result.config.budget.max_tokens_per_task).toBe(200000);
      expect(result.config.budget.max_iterations).toBe(3);
      expect(result.config.log_sink.enabled).toBe(true);
      expect(result.config.pr_poll_interval_seconds).toBe(300);
    });

    it("accepts a config without pr_poll_interval_seconds (optional field)", () => {
      const result = validateAgentYaml(fixture("valid-minimal.yaml"), { schema });
      expect(result.valid).toBe(true);
      if (!result.valid) return;
      expect(result.config.pr_poll_interval_seconds).toBeUndefined();
    });

    it("accepts a minimal valid config", () => {
      const result = validateAgentYaml(fixture("valid-minimal.yaml"), { schema });
      expect(result.valid).toBe(true);
      if (!result.valid) return;
      expect(result.config.enabled).toBe(false);
      expect(result.config.jitter_max_seconds).toBe(0);
      expect(result.config.budget.max_tokens_per_task).toBe(1);
    });

    it("returns a typed AgentConfig", () => {
      const result = validateAgentYaml(fixture("valid-agent.yaml"), { schema });
      expect(result.valid).toBe(true);
      if (!result.valid) return;
      const config: AgentConfig = result.config;
      expect(config.budget.max_iterations).toBe(3);
    });
  });

  describe("missing required fields", () => {
    it("rejects config missing watches, budget, and log_sink", () => {
      const result = validateAgentYaml(fixture("missing-required.yaml"), { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      const paths = result.errors.map((e) => e.message);
      expect(paths.some((m) => m.includes("watches"))).toBe(true);
      expect(paths.some((m) => m.includes("budget"))).toBe(true);
      expect(paths.some((m) => m.includes("log_sink"))).toBe(true);
    });

    it("provides human-readable messages for missing fields", () => {
      const result = validateAgentYaml(fixture("missing-required.yaml"), { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      for (const err of result.errors) {
        expect(err.message).toBeTruthy();
        expect(err.path).toBeTruthy();
      }
    });
  });

  describe("unknown fields", () => {
    it("rejects config with an unknown top-level field", () => {
      const result = validateAgentYaml(fixture("unknown-field.yaml"), { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(
        result.errors.some((e) => e.message.includes("agent_id")),
      ).toBe(true);
    });
  });

  describe("bad types", () => {
    it("rejects config with wrong types", () => {
      const result = validateAgentYaml(fixture("bad-types.yaml"), { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(result.errors.length).toBeGreaterThan(0);
      // watches should be an array
      expect(
        result.errors.some(
          (e) => e.path.includes("watches") || e.message.includes("array"),
        ),
      ).toBe(true);
    });
  });

  describe("constraint violations", () => {
    it("rejects empty watches array", () => {
      const result = validateAgentYaml(fixture("empty-watches.yaml"), { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(
        result.errors.some((e) => e.message.includes("at least")),
      ).toBe(true);
    });

    it("rejects zero max_tokens_per_task", () => {
      const yaml = `
watches:
  - git@github.com:org/repo.git
enabled: true
jitter_max_seconds: 0
budget:
  max_tokens_per_task: 0
  max_iterations: 1
log_sink:
  enabled: true
`;
      const result = validateAgentYaml(yaml, { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(
        result.errors.some(
          (e) =>
            e.path.includes("max_tokens_per_task") && e.message.includes(">="),
        ),
      ).toBe(true);
    });

    it("rejects pr_poll_interval_seconds: 0 (minimum is 1)", () => {
      const yaml = `
watches:
  - git@github.com:org/repo.git
enabled: true
jitter_max_seconds: 0
budget:
  max_tokens_per_task: 100
  max_iterations: 1
log_sink:
  enabled: true
pr_poll_interval_seconds: 0
`;
      const result = validateAgentYaml(yaml, { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(
        result.errors.some(
          (e) =>
            e.path.includes("pr_poll_interval_seconds") && e.message.includes(">="),
        ),
      ).toBe(true);
    });

    it("rejects negative jitter_max_seconds", () => {
      const yaml = `
watches:
  - git@github.com:org/repo.git
enabled: true
jitter_max_seconds: -1
budget:
  max_tokens_per_task: 100
  max_iterations: 1
log_sink:
  enabled: true
`;
      const result = validateAgentYaml(yaml, { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(
        result.errors.some(
          (e) =>
            e.path.includes("jitter_max_seconds") && e.message.includes(">="),
        ),
      ).toBe(true);
    });
  });

  describe("YAML parse errors", () => {
    it("returns an error for invalid YAML", () => {
      const result = validateAgentYaml("{{invalid yaml", { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(result.errors[0].message).toContain("YAML parse error");
    });

    it("rejects a scalar document", () => {
      const result = validateAgentYaml("just a string", { schema });
      expect(result.valid).toBe(false);
      if (result.valid) return;
      expect(result.errors[0].message).toContain("mapping");
    });

    it("rejects an empty document", () => {
      const result = validateAgentYaml("", { schema });
      expect(result.valid).toBe(false);
    });
  });
});

